import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"Personal schedules","description":"","frontmatter":{},"headers":[],"relativePath":"guide/schedules.md","filePath":"guide/schedules.md"}'),d={name:"guide/schedules.md"};function s(r,e,h,i,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="personal-schedules" tabindex="-1">Personal schedules <a class="header-anchor" href="#personal-schedules" aria-label="Permalink to &quot;Personal schedules&quot;">​</a></h1><p>Most people work the standup&#39;s days. Some don&#39;t: a four-day week, a Tuesday-to-Saturday rota, an ad hoc contractor, or just a comp-off after a weekend release. Personal schedules keep those people from being prompted on days they don&#39;t work — and from being counted as missing.</p><h2 id="two-building-blocks" tabindex="-1">Two building blocks <a class="header-anchor" href="#two-building-blocks" aria-label="Permalink to &quot;Two building blocks&quot;">​</a></h2><p><strong>A personal week</strong> overrides the standup&#39;s days for one person:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>Follow the standup (default)</td><td>Expected on every day the standup runs</td></tr><tr><td>Custom week, e.g. <code>mon-thu</code></td><td>Expected only on those weekdays</td></tr><tr><td>Ad hoc</td><td>No fixed days — expected only on dates marked <em>working</em></td></tr></tbody></table><p><strong>Dated overrides</strong> mark single days or ranges as <em>off</em> or <em>working</em>, with a short reason. Comp-off after a weekend shift is an <em>off</em> override on the weekday; an ad hoc person marks their <em>working</em> days. Both can be set ahead.</p><p>When a run opens, someone is expected only if the date is a working day for them and not overridden off. Everyone else starts the run as <strong>away</strong> with a reason — day off, not a working day, vacation, or calendar out-of-office — gets no prompt, is not counted as missing, and shows under <em>Away</em> on the overview and in reports. A standup still only runs on its own days, so a Saturday worker is not prompted on Saturday unless the standup itself includes Saturday.</p><h2 id="from-chat" tabindex="-1">From Chat <a class="header-anchor" href="#from-chat" aria-label="Permalink to &quot;From Chat&quot;">​</a></h2><p>DM the bot:</p><table tabindex="0"><thead><tr><th>Message</th><th>Effect</th></tr></thead><tbody><tr><td><code>off tomorrow comp off</code></td><td>Tomorrow off, with a reason</td></tr><tr><td><code>off 22 sep to 24 sep sick</code></td><td>A range off (up to 31 days — longer absences use <code>vacation</code>)</td></tr><tr><td><code>working sat</code></td><td>An extra working day (ad hoc people use this for every day they work)</td></tr><tr><td><code>off list</code></td><td>What&#39;s coming up, with each entry&#39;s status</td></tr><tr><td><code>off cancel &lt;date&gt;</code></td><td>Withdraw an entry</td></tr><tr><td><code>days mon-thu</code> · <code>days adhoc</code> · <code>days reset</code></td><td>Your own week, or back to the standup&#39;s</td></tr></tbody></table><p>Dates read naturally: <code>today</code>, <code>tomorrow</code>, a weekday name (the next one), <code>19 sep</code>, <code>sep 19</code>, <code>2026-09-19</code>. A date without a year means the coming one unless it is under three months back, so <code>2 jan</code> in December is next January. Only managers can change days in the past.</p><p>Managers, in the team space with an @mention of someone on that standup:</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>off @Asha tomorrow dentist</code> / <code>working @Asha sat</code></td><td>Mark someone away or working</td></tr><tr><td><code>off @Asha cancel &lt;date&gt;</code></td><td>Undo it</td></tr><tr><td><code>days @Asha tue-sat</code></td><td>Someone&#39;s personal week (<code>days mon,tue</code> without a mention still sets the standup&#39;s days)</td></tr></tbody></table><p>The person is DM&#39;d every time a manager changes their schedule, with the one-word reply that undoes it.</p><h2 id="from-the-console" tabindex="-1">From the console <a class="header-anchor" href="#from-the-console" aria-label="Permalink to &quot;From the console&quot;">​</a></h2><ul><li><strong>Standup → Settings → People</strong>: a grid with everyone in the standup&#39;s space, or everyone in the Google Group it follows (<a href="./directory.html#rosters-that-follow-a-google-group">group rosters</a>). Per person, tick whether they are on the standup, whether they are required, and which of the standup&#39;s days they work. Days the standup doesn&#39;t run are greyed out. The create form uses the same grid, with everyone in the space ticked to start with.</li><li><strong>Team → Edit schedule</strong> on any person: the week, the overrides list with who set each one, an add row, and <em>Mark away today</em>.</li><li><strong>My page → My schedule</strong>: the same controls for yourself, plus <em>Off today</em> and <em>Off tomorrow</em>.</li><li><strong>Standup → Overview</strong>: the <em>Away</em> group under today&#39;s run, with reason chips.</li><li><strong>Standup → Settings → Time off</strong>: the policy below.</li></ul><h2 id="who-can-change-what-the-time-off-policy" tabindex="-1">Who can change what: the time-off policy <a class="header-anchor" href="#who-can-change-what-the-time-off-policy" aria-label="Permalink to &quot;Who can change what: the time-off policy&quot;">​</a></h2><p>One setting per standup, under <em>Settings › Schedule</em>. A manager is an admin of a standup the person is on; managers and workspace admins can mark that person away or working in every mode.</p><p>A person changing their own schedule is bound by the policy of every standup they are on and don&#39;t administer. Someone who runs one team and sits on another still needs the other team&#39;s approval.</p><table tabindex="0"><thead><tr><th>Policy</th><th>A person marking themselves</th><th>Managers hear about it</th></tr></thead><tbody><tr><td><strong>Self-service</strong> (default)</td><td>Applies immediately</td><td>A digest DM of the day&#39;s self-service changes when the run closes</td></tr><tr><td><strong>Needs approval</strong></td><td>Becomes a request</td><td>A DM card with <strong>Approve</strong> / <strong>Decline</strong>, and the <em>Requests</em> tab under Team</td></tr><tr><td><strong>Managers only</strong></td><td>Refused with a pointer to the managers</td><td>—</td></tr></tbody></table><p>Under <em>Needs approval</em>, the first of the person&#39;s managers to act wins; workspace admins can act on any request, and nobody decides their own. Declining asks for a one-line reason, which is sent to the person. A request unanswered by the deadline of a standup that needs approval lapses — the person counts as expected for that run and is told so.</p><table tabindex="0"><thead><tr><th>A person under <em>Needs approval</em> or <em>Managers only</em></th><th>Allowed?</th></tr></thead><tbody><tr><td>Changing their personal week</td><td>No — there is no request for a week, so managers set it</td></tr><tr><td>Asking again for a day that is already approved</td><td>Yes — only the reason changes</td></tr><tr><td>Asking for the opposite of an approved day</td><td>No — ask a manager</td></tr><tr><td>Withdrawing a pending request, or giving back a day off</td><td>Yes</td></tr><tr><td>Dropping a working day a manager set</td><td>No</td></tr></tbody></table><p>Every change records who made it, when, and through which channel. Reports count an approved or manager-set away day as excused, never as missing; a declined or lapsed request counts as missing. A manager changing a past day corrects that day&#39;s run, except for people who submitted. Each standup&#39;s managers get the digest of a change once, whichever team&#39;s run closes first.</p><h2 id="leave-in-chat" tabindex="-1">Leave in Chat and Calendar <a class="header-anchor" href="#leave-in-chat" aria-label="Permalink to &quot;Leave in Chat and Calendar {#leave-in-chat}&quot;">​</a></h2><p>With <strong>Settings → General → Leave in Chat and Calendar</strong> on, people&#39;s leave shows where their teammates look. It belongs to the person, not a standup: one status and one event, however many standups they&#39;re on.</p><table tabindex="0"><thead><tr><th>Leave</th><th>Chat custom status</th><th>Calendar</th></tr></thead><tbody><tr><td>Days off (set, or approved)</td><td>🌴 <em>On leave until Mon 20 Oct</em> from the first day, expiring after the last</td><td>An <em>On leave</em> out-of-office event on their primary calendar, 00:00 on the first day to 00:00 after the last, in their timezone</td></tr><tr><td>Vacation mode, on every standup</td><td>🌴 <em>On leave</em>, until they switch it off</td><td>Nothing: there is no end date</td></tr></tbody></table><ul><li>Days off a few days apart are one period when the days between are days they don&#39;t work, such as a weekend.</li><li>Pending, declined and withdrawn days don&#39;t count.</li><li>The status replaces whatever status they had, which isn&#39;t restored.</li><li>When days change, the status and event follow. When they&#39;re cancelled, both go, but a status the person has since changed is left alone.</li><li><strong>Decline invites during leave</strong> sets what the event does with clashing invites: nothing (the default), new invites only, or all clashes. Declines say <em>I&#39;m on leave until Mon 20 Oct.</em></li><li>The replies to <code>off</code>, <code>vacation</code> and <code>back</code>, and a manager&#39;s approval, say that Chat and Calendar will show it.</li><li>When Google refuses, for example a missing scope or an unknown email, the latest failure shows under <strong>Settings → General</strong> and is retried hourly.</li></ul><p>It needs two scopes on the service account&#39;s domain-wide delegation; see <a href="./directory.html#leave-in-chat">Directory and group rosters</a>. Google allows custom statuses on Business and Enterprise editions.</p><h2 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h2><p>Webhooks receive two more events: <code>schedule_change</code> (person, summary, who, channel) and <code>time_off_request</code> (person, dates, working, reason, request ids). The JSON API exposes the same controls under <code>/me/schedule</code>, <code>/me/overrides</code>, <code>/people/:userName/schedule</code>, <code>/people/:userName/overrides</code> and <code>/requests</code> — see <a href="./api.html">JSON API</a>. MCP tokens with the <code>schedule</code> scope get <code>set_working_days</code>, <code>set_days_off</code>, <code>cancel_day_off</code>, <code>decide_time_off_request</code> and <code>update_my_settings</code>; <code>get_schedule</code> and <code>list_time_off_requests</code> come with <code>read</code> — see <a href="./mcp.html">Claude Code and MCP</a>. Tools act as the token&#39;s owner under the same policy.</p>',30)])])}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
